def get_minimum_difference_brute(root):
    values = []
    def collect(node):
        if node:
            collect(node.left); values.append(node.val); collect(node.right)
    collect(root)
    best = float('inf')
    for i in range(len(values)):
        for j in range(i + 1, len(values)):                 # check every pair directly
            best = min(best, abs(values[i] - values[j]))
    return best

