public class Main {
    static Integer prev = null;
    static int minDiff = Integer.MAX_VALUE;
    static int getMinimumDifference(TreeNode root) {
        inorder(root);
        return minDiff;
    }
    static void inorder(TreeNode node) {
        if (node == null) return;
        inorder(node.left);
        if (prev != null) minDiff = Math.min(minDiff, node.val - prev);   // only adjacent pairs
        prev = node.val;
        inorder(node.right);
    }
}

