int prevVal = INT_MIN, minDiff = INT_MAX;
bool hasPrev = false;
void inorder(TreeNode* node) {
    if (!node) return;
    inorder(node->left);
    if (hasPrev) minDiff = min(minDiff, node->val - prevVal);            // only adjacent pairs
    prevVal = node->val; hasPrev = true;
    inorder(node->right);
}
int getMinimumDifference(TreeNode* root) {
    inorder(root);
    return minDiff;
}
